import{_ as e,o,c as r,a3 as t}from"./chunks/framework.BFeCKmyl.js";const p=JSON.parse('{"title":"Favoritos no menu lateral","description":"","frontmatter":{"title":"Favoritos no menu lateral","id":"eproc-favoritos-menu-lateral","plataforma":"eproc","grupo":"Geral do eproc","plano":"free","desde":"1.1.0","padrao":"ligado"},"headers":[],"relativePath":"funcionalidades/eproc-favoritos-menu-lateral.md","filePath":"funcionalidades/eproc-favoritos-menu-lateral.md"}'),s={name:"funcionalidades/eproc-favoritos-menu-lateral.md"};function l(i,a,n,d,u,c){return o(),r("div",null,a[0]||(a[0]=[t('<h1 id="favoritos-no-menu-lateral" tabindex="-1">Favoritos no menu lateral <a class="header-anchor" href="#favoritos-no-menu-lateral" aria-label="Permalink to &quot;Favoritos no menu lateral&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Mostra, logo abaixo da busca do menu lateral, uma grade de até 6 atalhos (como ícones de aplicativo) para as rotinas que você mais abre pelo menu. A lista se monta sozinha, a cada clique num item do menu.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, menu lateral, abaixo do campo de busca, sob o título &quot;Buscas recentes&quot;.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Use o menu lateral normalmente. Cada clique numa rotina conta pontos para ela.</li><li>As rotinas mais usadas aparecem na grade. Clique num atalho para abri-la.</li><li>Clique com o botão direito num atalho para: <ul><li><strong>Fixar</strong>: o atalho passa a ocupar sempre uma vaga, com prioridade sobre os demais;</li><li><strong>Desafixar</strong>;</li><li><strong>Remover dos favoritos</strong>: o contador daquela rotina recomeça do zero.</li></ul></li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Opção</th><th>Padrão</th><th>Efeito</th></tr></thead><tbody><tr><td>Número de fileiras de atalhos</td><td>2 fileiras (6 atalhos)</td><td>Também pode ser &quot;1 fileira (3 atalhos)&quot;.</td></tr></tbody></table><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>Só contam os cliques feitos no menu lateral ou na própria grade. Rotinas abertas por outros caminhos não entram.</li><li>A grade segue o tema claro ou escuro do menu lateral do eproc.</li></ul>',11)]))}const h=e(s,[["render",l]]);export{p as __pageData,h as default};
